         75% {
            -webkit-transform: scale(.9);
            opacity: .3
         }

         100% {
            -webkit-transform: scale(1);
            opacity: 0
         }
      }

      @keyframes pulse2 {
         0% {
            -webkit-transform: scale(0);
            transform: scale(0);
            opacity: 0
         }

         25% {
            -webkit-transform: scale(.3);
            transform: scale(.3);
            opacity: 1
         }

         50% {
            -webkit-transform: scale(.6);
            transform: scale(.6);
            opacity: .6
         }

         75% {
            -webkit-transform: scale(.9);
            transform: scale(.9);
            opacity: .3
